export const weinArtikelIds = ['wein/wallis', 'wein/lavaux', 'wein/varen', 'wein/rebsorten'];

export function weinLocale(locale: Locale): FamilieText | null {
  if (locale === 'de') return null;
  const text = uebersicht[locale];
  return {
    ...text,
    blocks: [
      ...text.blocks,
      links([
        ['/leukerbad/wein/lavaux/', locale === 'fr' ? 'Lavaux' : 'Lavaux'],
        ['/leukerbad/wein/varen/', 'Varen'],
        ['/leukerbad/wein/wallis/', locale === 'en' ? 'Valais wine regions' : locale === 'fr' ? 'Les régions viticoles' : 'Le regioni del vino'],
        ['/leukerbad/wein/rebsorten/', locale === 'en' ? 'Grape varieties' : locale === 'fr' ? 'Les cépages' : 'I vitigni'],
        ['/wohnungen/alpine-siesta/', locale === 'en' ? 'The apartment' : locale === 'fr' ? 'L’appartement' : 'L’appartamento'],
        ['/leukerbad/familie/', locale === 'en' ? 'Family days in Leukerbad' : locale === 'fr' ? 'Les jours en famille à Loèche-les-Bains' : 'Le giornate in famiglia a Leukerbad'],
      ]),
    ],
  };
}

export function weinArtikel(locale: Locale, id: string): ArtikelText | null {
  if (locale === 'de') return null;
  return artikel[locale][id] ?? null;
}
